head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF30700";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":3
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf30700' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf30700.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_menuLink_onclick
 * @description 「아이디 신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_menuLink_onclick = function(e){
    try {
        menuLink(05001)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf30700.btn_menuLink_onclick' }); }
};

/**
 * @method
 * @name btn_corpNew_onclick
 * @description btn_corpNew 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_corpNew_onclick = async function(e){
    try {
        await scwin.corp_new()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf30700.btn_corpNew_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name corp_new
 * @description corp new 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.corp_new = async function () {
    await $c.win.alert("\n처음화면 '발행기관 조회'에서 회사명 검색 후\n\n기존 발행기관 코드 유무여부를 우선 확인하시기 바랍니다.\n\n조회된 발행기관 코드가 없는 경우\n\n'발행기관 등록'을 이용하시기 바랍니다.");
    menuLink('05000');
};
